(function(){
  let time=0;
  let particles=[];
  const N=130;
  function rand(a,b){return a+Math.random()*(b-a);}
  function makeDrop(){
    return {t:Math.random(), speed:rand(0.015,0.045), size:rand(1.5,4.5), offset:rand(0,Math.PI*2), amp:rand(10,34), trail:[], hue:Math.random()};
  }
  for(let i=0;i<N;i++) particles.push(makeDrop());

  function pointFor(p,t){
    const w=W(), h=H();
    let tt=(p.t+t*p.speed)%1;
    let bx=w*0.06+tt*w*0.88;
    let by=h*0.06+tt*h*0.88;
    let wobble=Math.sin(tt*Math.PI*4+p.offset+t*0.4)*p.amp;
    let angle=Math.atan2(h,w);
    let px=bx+Math.cos(angle+Math.PI/2)*wobble;
    let py=by+Math.sin(angle+Math.PI/2)*wobble;
    let cx=w/2, cy=h/2;
    let dx=px-cx, dy=py-cy;
    let dist=Math.sqrt(dx*dx+dy*dy)||0.001;
    let minDist=Math.min(w,h)*0.3;
    if(dist<minDist){
      let push=(minDist-dist);
      px+=dx/dist*push;
      py+=dy/dist*push;
    }
    return {x:px,y:py};
  }

  let leaves=[];
  const LN=14;
  for(let i=0;i<LN;i++){
    leaves.push({
      ax: rand(0,1)<0.5? rand(0,0.22):rand(0.78,1),
      ay: rand(0,1),
      r: rand(6,13),
      rot: rand(0,Math.PI*2),
      rotSpeed: rand(-0.004,0.004),
      phase: rand(0,Math.PI*2),
      speed: rand(0.2,0.5),
      colIdx: Math.floor(rand(0,3))
    });
  }

  function hexA(hex, alpha){
    if(!hex) return 'rgba(255,255,255,'+alpha+')';
    const h=hex.replace('#','');
    const r=parseInt(h.substring(0,2),16);
    const g=parseInt(h.substring(2,4),16);
    const b=parseInt(h.substring(4,6),16);
    return 'rgba('+r+','+g+','+b+','+alpha+')';
  }

  function drawBokeh(x,y,r){
    const g=ctx.createRadialGradient(x,y,0,x,y,r);
    g.addColorStop(0, hexA(PALETTE[1]||PALETTE[0],0.28));
    g.addColorStop(1, hexA(PALETTE[1]||PALETTE[0],0));
    ctx.save();
    ctx.fillStyle=g;
    ctx.beginPath();
    ctx.arc(x,y,r,0,Math.PI*2);
    ctx.fill();
    ctx.restore();
  }

  function frame(){
    time+=0.016;
    const w=W(), h=H();
    ctx.clearRect(0,0,w,h);

    for(let i=0;i<3;i++){
      const grad=ctx.createLinearGradient(w*0.05,h*0.1,w*0.95,h*0.9);
      grad.addColorStop(0, hexA(PALETTE[0],0.0));
      grad.addColorStop(0.3+i*0.1, hexA(PALETTE[1]||PALETTE[0], 0.22));
      grad.addColorStop(0.6+i*0.1, hexA(PALETTE[0], 0.12));
      grad.addColorStop(1, hexA(PALETTE[1]||PALETTE[0], 0.0));
      ctx.save();
      ctx.strokeStyle=grad;
      ctx.lineWidth=18+i*10;
      ctx.lineCap='round';
      ctx.beginPath();
      let off=i*40 + Math.sin(time*0.2+i)*20;
      ctx.moveTo(w*0.04, h*0.1+off);
      ctx.bezierCurveTo(w*0.35, h*0.3+off, w*0.55,h*0.55+off, w*0.96, h*0.92+off);
      ctx.stroke();
      ctx.restore();
    }

    drawBokeh(w*0.12,h*0.14, w*0.22);
    drawBokeh(w*0.88,h*0.86, w*0.2);

    leaves.forEach(lf=>{
      lf.rot+=lf.rotSpeed;
      const lx = lf.ax*w + Math.sin(time*lf.speed+lf.phase)*w*0.03;
      const ly = lf.ay*h + Math.cos(time*lf.speed*0.7+lf.phase)*h*0.02;
      ctx.save();
      ctx.translate(lx,ly);
      ctx.rotate(lf.rot);
      ctx.globalAlpha=0.5;
      ctx.fillStyle=PALETTE[lf.colIdx%3];
      ctx.beginPath();
      ctx.ellipse(0,0,lf.r,lf.r*0.55,0,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    });

    particles.forEach(p=>{
      const pt=pointFor(p,time);
      p.trail.push({x:pt.x,y:pt.y});
      if(p.trail.length>10) p.trail.shift();
      for(let j=0;j<p.trail.length;j++){
        const tp=p.trail[j];
        const a=(j/p.trail.length);
        ctx.save();
        ctx.globalAlpha=a*0.55;
        ctx.fillStyle=PALETTE[0];
        ctx.beginPath();
        ctx.arc(tp.x,tp.y,p.size*a,0,Math.PI*2);
        ctx.fill();
        ctx.restore();
      }
      ctx.save();
      ctx.shadowColor=PALETTE[0];
      ctx.shadowBlur=10;
      ctx.globalAlpha=0.9;
      ctx.fillStyle=PALETTE[2]||PALETTE[0];
      ctx.beginPath();
      ctx.arc(pt.x,pt.y,p.size,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    });

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
